body:
This whole file duplicates `drivers/apple_embedded/export/godot_plugin_config.h`. I think it's fine to use `drivers/apple_embedded/export/godot_plugin_config.h` to simplify code.

```
➜  godot git:(apple/ios-visionos-4.5) ✗ diff drivers/apple_embedded/export/godot_plugin_config.h platform/visionos/export/godot_plugin_config.h
32a33
> #include "core/error/error_list.h"
53c54
< struct PluginConfigAppleEmbedded {
---
> struct PluginConfigVisionOS {
124c125
<       static bool validate_plugin(PluginConfigAppleEmbedded &plugin_config);
---
>       static bool validate_plugin(PluginConfigVisionOS &plugin_config);
126c127
<       static String get_plugin_main_binary(PluginConfigAppleEmbedded &plugin_config, bool p_debug);
---
>       static String get_plugin_main_binary(PluginConfigVisionOS &plugin_config, bool p_debug);
128c129
<       static uint64_t get_plugin_modification_time(const PluginConfigAppleEmbedded &plugin_config, const String &config_path);
---
>       static uint64_t get_plugin_modification_time(const PluginConfigVisionOS &plugin_config, const String &config_path);
130c131
<       static PluginConfigAppleEmbedded load_plugin_config(Ref<ConfigFile> config_file, const String &path);
---
>       static PluginConfigVisionOS load_plugin_config(Ref<ConfigFile> config_file, const String &path);
```

